import json

with open('./data.json', 'r') as f:
    data = json.load(f)

target_timestamp = "2025-05-26T10:50:51.169Z"

# Search recursively
def find_entry_by_timestamp(obj, target):
    if isinstance(obj, dict):
        if obj.get('timestamp') == target:
            return obj
        for value in obj.values():
            result = find_entry_by_timestamp(value, target)
            if result:
                return result
    elif isinstance(obj, list):
        for item in obj:
            result = find_entry_by_timestamp(item, target)
            if result:
                return result
    return None

entry = find_entry_by_timestamp(data, target_timestamp)
if entry:
    print(json.dumps(entry, indent=2))
    if 'level' in entry:
        print(f"\nLevel: {entry['level']}")
else:
    print("Entry not found. Showing data structure:")
    if isinstance(data, dict):
        print(f"Keys: {list(data.keys())}")
        if 'logs' in data:
            print(f"Number of logs: {len(data['logs'])}")
            if data['logs']:
                print(f"First log: {json.dumps(data['logs'][0], indent=2)}")
